changeSet.sql:

ALTER TABLE event
    ADD COLUMN usac_tx_username VARCHAR(255) NOT NULL,
    ADD COLUMN usac_cd_id UUID NOT NULL;

CREATE INDEX idx_event_usac_tx_username
    ON event (usac_tx_username);

CREATE INDEX idx_event_usac_cd_id
    ON event (usac_cd_id);

rollback.sql:

DROP INDEX IF EXISTS idx_event_usac_tx_username;
DROP INDEX IF EXISTS idx_event_usac_cd_id;

ALTER TABLE event
    DROP COLUMN IF EXISTS usac_tx_username,
    DROP COLUMN IF EXISTS usac_cd_id;
